* {
  box-sizing: border-box;
  padding: 0;
  margin: 0;
}

:root {
  --header-height: 3.5rem;
  --first-color: hsl(28, 88%, 62%);
  --title-color: hsl(0, 0%, 95%);
  --text-color: hsl(0, 0%, 75%);
  --body-color: hsl(0, 0%, 6%);
  --body-font: "Montserrat", sans-serif;
  --second-font: "Dancing Script", cursive;
  --h2-font-size: 1.25rem;
  --small-font-size: 0.813rem;
  --font-semi-bold: 600;
  --z-tooltip: 10;
  --z-fixed: 100;
}

/* Global Styles */
body {
  background-color: var(--body-color);
  color: var(--text-color);
  font-family: var(--body-font);
  line-height: 1.6;
  padding-top: var(--header-height); /* To avoid overlap with the fixed navbar */
}

ul {
  list-style: none;
}

a {
  text-decoration: none;
}

/* Navbar Styling */
.header {
  position: fixed;
  width: 100%;
  top: 0;
  left: 0;
  background-color: transparent;
  z-index: var(--z-fixed);
}

.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: relative;
  padding: 10px 20px;
  height: var(--header-height);
  margin: 1rem;
}

.nav_item {
  margin: 0 10px;
  padding: 5px 10px;
}

.nav__logo {
  color: var(--first-color);
  transition: color 0.4s;
  font-size: var(--h2-font-size);
  font-family: var(--second-font);
}

.nav__toggle,
.nav__close {
  font-size: 1.5rem;
  color: var(--title-color);
  cursor: pointer;
}

.nav__cta {
  background-color: var(--first-color);
  color: var(--title-color);
  border: none;
  border-radius: 4px;
  cursor: pointer;
  transition: background-color 0.3s ease;
  padding: 0.75rem 1.5rem;
}

.nav__list {
  display: flex;
  flex-direction: row;
  row-gap: 20px;
  gap: 120px;
}

.nav__link {
  color: var(--title-color);
  font-weight: var(--font-semi-bold);
  transition: color 0.4s;
}

.nav__link:hover {
  color: var(--first-color);
}

.nav__close {
  position: absolute;
  top: 1rem;
  right: 1.5rem;
}

.show-menu {
  right: 0;
}

/* Page Content */
.home-container {
  text-align: center;
  padding: 2rem 1rem;
}

.home-title {
  font-size: 2.5rem;
  color: var(--title-color);
  margin-bottom: 1.5rem;
  font-family: var(--second-font);
}

.home-text {
  font-size: 1.125rem;
  color: var(--text-color);
  max-width: 600px;
  margin: 0 auto 2rem;
}

.home-button {
  background-color: var(--first-color);
  color: var(--title-color);
  border: none;
  border-radius: 4px;
  padding: 1rem 2rem;
  font-size: 1rem;
  font-weight: var(--font-semi-bold);
  cursor: pointer;
  transition: background-color 0.3s ease;
}

.home-button:hover {
  background-color: hsl(28, 88%, 50%);
}
